"""Keep recall quality, source delivery, speech checks, and sampled paging separate."""
import datetime,hashlib,json,statistics
from pathlib import Path
from zoneinfo import ZoneInfo
sessions=[json.loads(s) for s in Path('eval/dev/exchanges.jsonl').read_text().splitlines()]
steps={s['id']:s for session in sessions for s in session['steps'] if 'say' in s}
output=[]
for family,stamp in [('baseline',None),('candidate','1792111824'),('integrated','1792112234')]:
    path=Path(f'bench/results/2026-10-15-exchanges-{family}-replay-1.jsonl')
    raw=[json.loads(s) for s in path.read_text().splitlines()]
    verdicts=[json.loads(s) for s in path.with_suffix('.judged.jsonl').read_text().splitlines()]
    row={'family':family,'release':raw[-1]['release'],'groups':{}}
    for group in ['dialogue-recall','dialogue-correction','dialogue-negative']:
        selected=[r for r in verdicts if steps[r['id']].get('capability')==group]
        row['groups'][group]={'correct':sum(r['pass'] for r in selected),'n':len(selected),'failures':[r['id'] for r in selected if not r['pass']]}
    if stamp:
        turns=[json.loads(s) for s in Path(f'build/exchanges-{family}-turns.jsonl').read_text().splitlines()]
        assert len(turns)==len(raw)-1
        by_id=dict(zip((r['id'] for r in raw[:-1]),turns,strict=True))
        source_checks=[]
        for ident,turn in by_id.items():
            if steps[ident].get('capability')!='dialogue-recall': continue
            sources=steps[ident]['evidence'] if 'companies' in ident else steps[ident]['evidence'][:1]
            for source in sources:
                pid=by_id[source]['frame_id']
                text='\n'.join(part['text'] for message in turn['prompt'] if isinstance(message['content'],list) for part in message['content'] if part.get('type')=='text')
                source_checks.append(pid in turn['exchanges'] and str(pid) in text and json.dumps(by_id[source]['question']) in text and json.dumps(by_id[source]['answer']) in text)
        row['opening_replies_supplied_as_dialogue']={'correct':sum(source_checks),'n':len(source_checks)}
        prefix=Path(f'build/exchanges-{family}-{stamp}')
        vm=[]
        for line in prefix.with_suffix('.vmstat').read_text().splitlines():
            cells=line.split()
            if len(cells)==20 and cells[0].isdigit():
                ts=datetime.datetime.fromisoformat(' '.join(cells[-2:])).replace(tzinfo=ZoneInfo('America/New_York')).timestamp()
                vm.append((ts,int(cells[6]),int(cells[7])))
        intervals=[(r['speech_start'],max(r['done'],r['first_audio']+r['audio_s'])) for r in turns]
        samples=[(si,so) for ts,si,so in vm[1:] if any(a<ts and b>ts-1 for a,b in intervals)]
        available=[int(s.split()[-1]) for s in prefix.with_suffix('.free').read_text().splitlines() if s.startswith('Mem:')]
        paging=json.loads(prefix.with_suffix('.paging').read_text())
        row['resources']={'sampled_mem_available_min_bytes':min(available),'free_samples':len(available),'response_overlapping_intervals':len(samples),'paging_intervals':sum(si>0 or so>0 for si,so in samples),'sampled_swap_in_kib':sum(si for si,so in samples),'sampled_swap_out_kib':sum(so for si,so in samples),'whole_run_swap_delta_bytes':{k:(paging['after'][k]-paging['before'][k])*paging['page_bytes'] for k in paging['before']},'answer_done_p50_s':statistics.median(r['done']-r['speech_end'] for r in turns)}
        row['raw_resources']={f'robot:/home/qdrant/qdrant-robot/shared/results/{prefix.name}.{suffix}':hashlib.sha256(prefix.with_suffix('.'+suffix).read_bytes()).hexdigest() for suffix in ['free','vmstat','paging']}
        checks=[json.loads(s) for s in next(Path('bench/results').glob(f'2026-10-15-exchanges-{family}-token-checks-*.jsonl')).read_text().splitlines()]
        row['rendered_prompt_tokens']={'maximum':max(r['tokens'] for r in checks),'n':len(checks),'all_fit':all(r['fits'] for r in checks)}
    output.append(row)
record={'summary':'exchange-memory-analysis','runs':output,'limits':'Development oracle dialogue only. vmstat first cumulative row excluded. One-second intervals overlap submission through synthesized speech completion and have boundary uncertainty. Whole-run page counters include model loading. Samples do not establish peak headroom or paging safety. Replays do not measure physical audible latency. Source IDs are checked against rendered dialogue as well as evaluator evidence flags.','analysis_python':Path(__file__).read_text()}
Path('bench/results/2026-10-15-exchanges-analysis.jsonl').write_text(json.dumps(record)+'\n')
for row in output: print(json.dumps(row))
